@router.post("/", summary="新增站点", response_model=schemas.Response)
async def add_site(
    *,
    db: AsyncSession = Depends(get_async_db),
    site_in: schemas.Site,
    _: User = Depends(get_current_active_manage_user_async),
) -> Any:
    """
    新增站点
    """
    if not site_in.url:
        return schemas.Response(success=False, message="站点地址不能为空")
    if SitesHelper().auth_level < 2:
        return schemas.Response(
            success=False, message="用户未通过认证，无法使用站点功能！"
        )
    domain = StringUtils.get_url_domain(site_in.url)
    site_info = await SitesHelper().async_get_indexer(domain)
    if not site_info:
        return schemas.Response(
            success=False, message="该站点不支持，请检查站点域名是否正确"
        )
    if await Site.async_get_by_domain(db, domain):
        return schemas.Response(success=False, message=f"{domain} 站点己存在")
    # 保存站点信息
    site_in.domain = domain
    # 校正地址格式
    _scheme, _netloc = StringUtils.get_url_netloc(site_in.url)
    site_in.url = f"{_scheme}://{_netloc}/"
    site_in.name = site_info.get("name")
    site_in.id = None
    site_in.public = 1 if site_info.get("public") else 0
    site = Site(**site_in.model_dump())
    site.create(db)
    # 通知站点更新
    await eventmanager.async_send_event(EventType.SiteUpdated, {"domain": domain})
    return schemas.Response(success=True)

def __parse_favicon(url: str, cookie: str, ua: str) -> Tuple[str, Optional[str]]:
    """
    解析站点favicon,返回base64 fav图标
    :param url: 站点地址
    :param cookie: Cookie
    :param ua: User-Agent
    :return:
    """
    favicon_url = urljoin(url, "favicon.ico")
    res = RequestUtils(cookies=cookie, timeout=30, ua=ua).get_res(url=url)
    if res:
        html_text = res.text
    else:
        logger.error(f"获取站点页面失败：{url}")
        return favicon_url, None
    html = etree.HTML(html_text)
    try:
        if StringUtils.is_valid_html_element(html):
            fav_link = html.xpath('//head/link[contains(@rel, "icon")]/@href')
            if fav_link:
                favicon_url = urljoin(url, fav_link[0])

        res = RequestUtils(cookies=cookie, timeout=15, ua=ua).get_res(url=favicon_url)
        if res:
            return favicon_url, base64.b64encode(res.content).decode()
        else:
            logger.error(f"获取站点图标失败：{favicon_url}")
    finally:
        if html is not None:
            del html
    return favicon_url, None

@eventmanager.register(EventType.SiteUpdated)
def cache_site_userdata(self, event: Event):
    """
    缓存站点用户数据
    """
    if not event:
        return
    event_data = event.event_data or {}
    # 主域名
    domain = event_data.get("domain")
    if not domain:
        return
    if str(domain).startswith("http"):
        domain = StringUtils.get_url_domain(domain)
    indexer = SitesHelper().get_indexer(domain)
    if not indexer:
        return
    # 刷新站点用户数据
    self.refresh_userdata(site=indexer) or {}

@router.get(
    "/reload/{plugin_id}", summary="重新加载插件", response_model=schemas.Response
)
def reload_plugin(
    plugin_id: str, _: User = Depends(get_current_active_superuser)
) -> Any:
    """
    重新加载插件
    """
    # 重新加载插件
    PluginManager().reload_plugin(plugin_id)
    # 注册插件服务
    register_plugin(plugin_id)
    return schemas.Response(success=True)
